DO $$ DECLARE definition text; BEGIN SELECT pg_get_functiondef('public.settle_appointment(uuid,jsonb,jsonb,boolean,text)'::regprocedure) INTO definition; definition:=replace(definition,'l||jsonb_build_object(''name'',t.name_nl', 'jsonb_build_object(''treatmentId'',t.id,''qty'',(l->>''qty'')::numeric,''unit'',coalesce(l->>''unit'',''''),''priceCents'',(l->>''priceCents'')::bigint,''discountCents'',(l->>''discountCents'')::bigint,''name'',t.name_nl'); EXECUTE definition; END $$;